cat > .local/take-replacement-2026-10-29/commit.mjs <<'EOF'
import {execFileSync} from 'node:child_process';
import {readFileSync,writeFileSync,openSync,closeSync} from 'node:fs';
import {resolve} from 'node:path';
const folder=resolve('.local/take-replacement-2026-10-29');
const paths=['crates/editor-api/src/operations/classic_takes.rs','crates/editor-api/src/operations/classic_takes/replacement.rs','crates/editor-api/tests/classic_takes.rs','classic/apps/web/src/core/__tests__/canonical-smart-takes.test.ts','classic/scripts/local-production/build.mjs','analysis/take-replacement-2026-10-29/README.md','analysis/take-replacement-2026-10-29/verification.json','.dip/tools/verify-take-replacement.mjs'];
const staged=execFileSync('git',['diff','--cached','--name-only','--',...paths,'.dip/config.json'],{encoding:'utf8'}).trim();
if(staged) throw Error('Task paths acquired staged changes; inspect before committing');
const base=JSON.parse(execFileSync('git',['show','HEAD:.dip/config.json'],{encoding:'utf8'}));
const working=JSON.parse(readFileSync('.dip/config.json','utf8'));
base.verification['take-replacement']=working.verification['take-replacement'];
const configPath=resolve(folder,'commit-config.json');writeFileSync(configPath,JSON.stringify(base,null,2)+'\n');
const env={...process.env,GIT_INDEX_FILE:resolve(folder,'commit-index')};
execFileSync('git',['read-tree','HEAD'],{env});
execFileSync('git',['add','--',...paths],{env});
const blob=execFileSync('git',['hash-object','-w',configPath],{encoding:'utf8'}).trim();
execFileSync('git',['update-index','--add','--cacheinfo','100644',blob,'.dip/config.json'],{env});
const log=openSync(resolve(folder,'commit.log'),'w');
try {execFileSync('git',['commit','-m','fix: replace smart takes within edited timelines'],{env,stdio:['ignore',log,log]});} finally {closeSync(log);}
// These paths had no staged changes before this task. Keep the shared index and
// new HEAD consistent without touching unrelated staged audit/work files.
